    "tags": [
      "gguf",
      "stream"
    ]
  },
  "capabilities": {
    "clone": [
      "speaker_reference",
      "long_form"
    ]
  },
  "options": {
    "request": [
      {
        "name": "language",
        "type": "string",
        "description": "Target synthesis language code used by the text frontend; default zh when no request transcript language or style language is provided.",
        "required": false,
        "default": "zh"
      },
      {
        "name": "temperature",
        "type": "float",
        "description": "T2S sampling temperature; must be positive, default 0.8.",
        "required": false,
        "min": 0.0,
        "default": 0.8
      },
      {
        "name": "top_p",
        "type": "float",
        "description": "T2S nucleus sampling probability; must be in (0, 1], default 0.8.",
        "required": false,
        "min": 0.0,
        "max": 1.0,
        "default": 0.8
      },
      {
        "name": "top_k",
        "type": "int",
        "description": "T2S top-k sampling limit; must be positive, default 30.",
        "required": false,
        "min": 1,
        "default": 30
      },
      {
        "name": "num_beams",
        "type": "int",
        "description": "T2S beam count; default 3. Set 1 for single-beam sampling.",
        "required": false,
        "min": 1,
        "default": 3
      },
      {
        "name": "repetition_penalty",
        "type": "float",
        "description": "T2S repetition penalty; must be positive, default 10.0.",
        "required": false,
        "min": 0.0,
        "default": 10.0
      },
      {
        "name": "max_tokens",
        "type": "int",
        "description": "Maximum T2S semantic sequence length including prompt tokens; default 1520.",
        "required": false,
        "min": 1,
        "default": 1520
