      {
        "name": "num_inference_steps",
        "type": "int",
        "description": "S2A flow-matching step count; default 25.",
        "required": false,
        "min": 1,
        "default": 25
      },
      {
        "name": "guidance_scale",
        "type": "float",
        "description": "S2A classifier-free guidance scale; default 0.7.",
        "required": false,
        "min": 0.0,
        "default": 0.7
      },
      {
        "name": "text_chunk_size",
        "type": "int",
        "description": "Maximum text tokens per generated segment; default 80.",
        "required": false,
        "min": 1,
        "default": 80
      },
      {
        "name": "text_chunk_mode",
        "type": "enum",
        "description": "Framework text chunking mode; default uses the standard word-budget chunker.",
        "values": [
          "default",
          "tag_aware",
          "japanese",
          "endline"
        ],
        "required": false,
        "default": "default"
      },
      {
        "name": "cross_fade_duration_sec",
        "type": "float",
        "description": "Cross-fade duration between generated segments in seconds; default 0.3.",
        "required": false,
        "min": 0.0,
        "default": 0.3
      },
      {
        "name": "edge_fade_duration_sec",
        "type": "float",
        "description": "Fade duration applied at segment edges in seconds; default 0.1.",
        "required": false,
        "min": 0.0,
        "default": 0.1
      },
      {
        "name": "edge_pad_duration_sec",
        "type": "float",
        "description": "Silence padding applied at segment edges in seconds; default 0.1.",
        "required": false,
        "min": 0.0,
        "default": 0.1
